"""Run only the newly selected physical30 reports on owned PostgreSQL UUIDs."""
from pathlib import Path
import hashlib,importlib.metadata,json,os,subprocess,sys,time
import xml.etree.ElementTree as ET
from sqlalchemy import create_engine,text
from sqlalchemy.engine import make_url
root=Path(r'F:\mb-r12-history30-20261019');out=Path(r'C:\Users\Consu\AppData\Local\Temp\metodobase-ci30-current-pg-first-20261019');out.mkdir(exist_ok=False)
tracked=subprocess.check_output(['git','ls-files','-z'],cwd=root).decode().split('\0')[:-1]
names=set(tracked)|{'tests/run_reviewed_ci29.py','tests/verify_history_index_ci.py','tests/check_history_index_reports.py','tests/test_history_index_ci_trust.py','tests/ci_history_index30/baseline.json','tests/ci_history_index30/ci29-before.yml'}
def photo():return {'files':{name:hashlib.sha256((root/name).read_bytes()).hexdigest() for name in sorted(names)},'packages':sorted((d.metadata['Name'],d.version) for d in importlib.metadata.distributions())}
before=photo();(out/'before.json').write_text(json.dumps(before,indent=2)+'\n',encoding='utf8')
configuration=json.loads(Path(r'C:\Users\Consu\AppData\Local\Temp\metodobase-qa-pg55483-private-ok6hrpyq/env.json').read_text(encoding='utf-8-sig'))
environment=dict(os.environ,PYTHONUTF8='1',PYTHONDONTWRITEBYTECODE='1',PYTHON_DOTENV_DISABLED='1')
for name in ['DATABASE_URL','MIGRATOR_DATABASE_URL','METODOBASE_TEST_DATABASE_URL','_METODOBASE_TEST_ROOT']:environment.pop(name,None)
for name in ['METODOBASE_TEST_MIGRATOR_URL','METODOBASE_TEST_POSTGRES_URL','METODOBASE_TEST_PG_BIN']:environment[name]=configuration[name]
evidence=out/'private-evidence';evidence.mkdir();environment['METODOBASE_TEST_EVIDENCE_DIR']=str(evidence)
base=[sys.executable,'-X','utf8','-B','tests/run_isolated.py']
commands=[('index',base+['tests/integration_personal_history_index_migrations.py','tests/integration_personal_history_ordered_query.py','-k','postgresql','-q','--tb=short','--junitxml='+str(out/'pytest-postgres-history-index.xml')]),
('restore',base+['tests/integration_personal_history_index_restore.py','-q','--tb=short','--junitxml='+str(out/'pytest-postgres-history-index-restore.xml')]),
('units',base+['tests/test_member_ci_trust.py','tests/test_member_browser_gate.py','tests/test_reviewed_ci28_archive.py','tests/test_history_index_ci_trust.py','-q','--tb=short','--junitxml='+str(out/'units.xml')]),
('reports',[sys.executable,'-X','utf8','-B','tests/check_history_index_reports.py','--directory',str(out)])]
rows=[]
for mode,command in commands:
    started=time.monotonic();result=subprocess.run(command,cwd=root,env=environment,capture_output=True,timeout=240)
    (out/(mode+'.stdout.private.log')).write_bytes(result.stdout);(out/(mode+'.stderr.private.log')).write_bytes(result.stderr)
    rows.append({'mode':mode,'command':command,'exit':result.returncode,'seconds':time.monotonic()-started})
    print(json.dumps({'mode':mode,'exit':result.returncode,'seconds':rows[-1]['seconds']}),flush=True)
    if result.returncode:break
after=photo();(out/'after.json').write_text(json.dumps(after,indent=2)+'\n',encoding='utf8')
cases={name:len(ET.parse(out/name).findall('.//testcase')) for name in ['pytest-postgres-history-index.xml','pytest-postgres-history-index-restore.xml','units.xml'] if (out/name).exists()}
pip=subprocess.run([sys.executable,'-m','pip','check'],capture_output=True);(out/'pip.log').write_bytes(pip.stdout+pip.stderr)
# Recheck only the two exact names generated by the maintained restore fixture.
owned=json.loads((evidence/'personal-history30-author-owned-created.json').read_bytes())['names'] if (evidence/'personal-history30-author-owned-created.json').exists() else []
closure=[]
if owned:
    assert len(owned)==2 and all(name.startswith(('metodobase_test_backup_','metodobase_test_restore_')) for name in owned)
    engine=create_engine(make_url(configuration['METODOBASE_TEST_MIGRATOR_URL']).set(database='postgres'))
    try:
        with engine.connect() as db:
            db.exec_driver_sql('SET TRANSACTION READ ONLY')
            for name in owned:closure.append({'database':name,'count':db.execute(text('SELECT count(*) FROM pg_database WHERE datname=:name'),{'name':name}).scalar_one()})
    finally:engine.dispose()
(out/'independent-restore-closure.json').write_text(json.dumps(closure,indent=2)+'\n',encoding='utf8')
summary={'head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip(),'results':rows,'sources_packages_stable':before==after,'source_files':len(names),'packages':len(before['packages']),'cases':cases,'pip_exit':pip.returncode,'owned_restore_closure':closure,'scope':'Actual newly selected physical30 PostgreSQL cases and maintained populated30 restore, isolated UUIDs. No browser/image/Actions/SLO.'}
(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n',encoding='utf8');print(json.dumps(summary))
assert len(rows)==4 and all(row['exit']==0 for row in rows) and before==after and pip.returncode==0
assert cases=={'pytest-postgres-history-index.xml':8,'pytest-postgres-history-index-restore.xml':1,'units.xml':74}
assert len(closure)==2 and all(row['count']==0 for row in closure)
